use std::collections::BTreeMap;
use std::io::{self, BufRead, Write};

fn parse_record(line: &str) -> Option<(&str, u64)> {
    let (category, value) = line.split_once(',')?;
    if category.is_empty()
        || !category.bytes().all(|byte| byte.is_ascii_alphanumeric())
        || value.is_empty()
        || !value.bytes().all(|byte| byte.is_ascii_digit())
    {
        return None;
    }

    // The digit check above ensures signs and whitespace are rejected before parsing.
    let value = value.parse().ok()?;
    Some((category, value))
}

fn aggregate<R: BufRead>(reader: R) -> io::Result<(BTreeMap<String, u64>, u64)> {
    let mut totals = BTreeMap::new();
    let mut skipped = 0_u64;

    for line in reader.lines() {
        let line = line?;
        match parse_record(&line) {
            Some((category, value)) => {
                let total = totals.entry(category.to_owned()).or_insert(0_u64);
                *total = total
                    .checked_add(value)
                    .ok_or_else(|| io::Error::other("category total overflow"))?;
            }
            None => {
                skipped = skipped
                    .checked_add(1)
                    .ok_or_else(|| io::Error::other("malformed line count overflow"))?;
            }
        }
    }

    Ok((totals, skipped))
}

fn run() -> io::Result<()> {
    let stdin = io::stdin();
    let (totals, skipped) = aggregate(stdin.lock())?;

    let stdout = io::stdout();
    let mut output = io::BufWriter::new(stdout.lock());
    for (category, total) in totals {
        writeln!(output, "{category},{total}")?;
    }
    output.flush()?;

    let stderr = io::stderr();
    let mut diagnostics = io::BufWriter::new(stderr.lock());
    writeln!(diagnostics, "skipped={skipped}")?;
    diagnostics.flush()
}

fn main() {
    if let Err(error) = run() {
        let _ = writeln!(io::stderr().lock(), "error: {error}");
        std::process::exit(1);
    }
}

