        assert_eq!(parse_record("Food9,42"), Some(("Food9", 42)));
        assert_eq!(parse_record("A,0"), Some(("A", 0)));

        for malformed in [
            "",
            ",1",
            "A,",
            "A,1,2",
            "A,+1",
            "A,-1",
            "A, 1",
            "A,1 ",
            " A,1",
            "A ,1",
            "é,1",
            "A,١",
            "A,18446744073709551616",
        ] {
            assert_eq!(parse_record(malformed), None, "accepted {malformed:?}");
        }
    }

