use std::error::Error;
use std::fmt;
use std::str::FromStr;

/// A version consisting of exactly three decimal `u16` components.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Version {
    major: u16,
    minor: u16,
    patch: u16,
}

impl Version {
    /// Returns the major component.
    pub const fn major(&self) -> u16 {
        self.major
    }

    /// Returns the minor component.
    pub const fn minor(&self) -> u16 {
        self.minor
    }

    /// Returns the patch component.
    pub const fn patch(&self) -> u16 {
        self.patch
    }
}

/// The reason a string could not be parsed as a [`Version`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ParseVersionError {
    /// The input did not contain exactly three dot-separated components.
    InvalidComponentCount,
    /// A component was empty, contained non-ASCII decimal digits, or had a leading zero.
    InvalidComponent,
    /// A component's value exceeded `u16::MAX`.
    ComponentOverflow,
}

impl fmt::Display for ParseVersionError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidComponentCount => {
                f.write_str("version must have exactly three components")
            }
            Self::InvalidComponent => {
                f.write_str("components must be ASCII decimal digits without leading zeroes")
            }
            Self::ComponentOverflow => f.write_str("component exceeds the u16 range"),
        }
    }
}

impl Error for ParseVersionError {}

impl FromStr for Version {
    type Err = ParseVersionError;

    fn from_str(input: &str) -> Result<Self, Self::Err> {
        if input.split('.').count() != 3 {
            return Err(ParseVersionError::InvalidComponentCount);
        }

        let mut components = input.split('.');
        let major = parse_component(
            components
                .next()
                .ok_or(ParseVersionError::InvalidComponentCount)?,
        )?;
        let minor = parse_component(
            components
                .next()
                .ok_or(ParseVersionError::InvalidComponentCount)?,
        )?;
        let patch = parse_component(
            components
                .next()
                .ok_or(ParseVersionError::InvalidComponentCount)?,
        )?;

        if components.next().is_some() {
            return Err(ParseVersionError::InvalidComponentCount);
        }

        Ok(Self {
            major,
            minor,
            patch,
        })
    }
}

fn parse_component(component: &str) -> Result<u16, ParseVersionError> {
    if component.is_empty()
        || (component.len() > 1 && component.starts_with('0'))
        || !component.bytes().all(|byte| byte.is_ascii_digit())
    {
        return Err(ParseVersionError::InvalidComponent);
    }

    component
        .parse()
        .map_err(|_| ParseVersionError::ComponentOverflow)
}

