    use std::str::FromStr;

    #[test]
    fn parses_three_components_and_exposes_them_read_only() {
        let version = Version::from_str("12.0.65535").unwrap();
        assert_eq!(version.major(), 12);
        assert_eq!(version.minor(), 0);
        assert_eq!(version.patch(), u16::MAX);
    }

    #[test]
    fn accepts_zero_components() {
        assert_eq!("0.0.0".parse::<Version>().unwrap().major(), 0);
    }

    #[test]
    fn rejects_invalid_component_counts() {
        for input in ["", "1", "1.2", "1.2.3.4"] {
            assert_eq!(
                input.parse::<Version>(),
                Err(ParseVersionError::InvalidComponentCount),
                "{input:?}"
            );
        }
    }

    #[test]
    fn rejects_empty_components() {
        for input in ["1..3", ".1.2", "1.2."] {
            assert_eq!(
                input.parse::<Version>(),
                Err(ParseVersionError::InvalidComponent),
                "{input:?}"
            );
        }
    }

    #[test]
    fn rejects_invalid_digits_and_leading_zeroes() {
        for input in [
            " 1.2.3", "1.2.3 ", "+1.2.3", "-1.2.3", "01.2.3", "1.02.3", "1.2.03", "١.2.3",
        ] {
            assert_eq!(
                input.parse::<Version>(),
                Err(ParseVersionError::InvalidComponent),
                "{input:?}"
            );
        }
    }

    #[test]
    fn rejects_components_larger_than_u16() {
        for input in ["65536.0.0", "0.65536.0", "0.0.65536"] {
            assert_eq!(
                input.parse::<Version>(),
                Err(ParseVersionError::ComponentOverflow),
                "{input:?}"
            );
        }
    }
}

