use std::error::Error;
use std::fmt;
use std::str::FromStr;

/// A version made up of exactly three decimal `u16` components.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Version {
    major: u16,
    minor: u16,
    patch: u16,
}

impl Version {
    /// Returns the major component.
    pub const fn major(&self) -> u16 {
        self.major
    }

    /// Returns the minor component.
    pub const fn minor(&self) -> u16 {
        self.minor
    }

    /// Returns the patch component.
    pub const fn patch(&self) -> u16 {
        self.patch
    }
}

/// The reason a string could not be parsed as a [`Version`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ParseVersionError {
    /// The input did not contain exactly three dot-separated components.
    InvalidComponentCount,
    /// A component was empty, contained non-ASCII decimal digits, or had a sign/whitespace.
    InvalidComponent,
    /// A component had a leading zero and more than one digit.
    LeadingZero,
    /// A component exceeded the range of `u16`.
    Overflow,
}

impl fmt::Display for ParseVersionError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidComponentCount => f.write_str("version must contain exactly three components"),
            Self::InvalidComponent => f.write_str("components must contain only ASCII decimal digits"),
            Self::LeadingZero => f.write_str("components must not have leading zeroes"),
            Self::Overflow => f.write_str("component exceeds the range of u16"),
        }
    }
}

impl Error for ParseVersionError {}

impl FromStr for Version {
    type Err = ParseVersionError;

    fn from_str(input: &str) -> Result<Self, Self::Err> {
        let components: Vec<_> = input.split('.').collect();
        if components.len() != 3 {
            return Err(ParseVersionError::InvalidComponentCount);
        }
        let major = parse_component(components[0])?;
        let minor = parse_component(components[1])?;
        let patch = parse_component(components[2])?;
        Ok(Self { major, minor, patch })
    }
}

fn parse_component(component: &str) -> Result<u16, ParseVersionError> {
    if component.is_empty() || !component.bytes().all(|b| b.is_ascii_digit()) {
        return Err(ParseVersionError::InvalidComponent);
    }
    if component.len() > 1 && component.starts_with('0') {
        return Err(ParseVersionError::LeadingZero);
    }
    component.parse().map_err(|_| ParseVersionError::Overflow)
}

