//! Parses and represents versions with exactly three decimal components.

use std::error::Error;
use std::fmt;
use std::str::FromStr;

/// A version containing three unsigned 16-bit decimal components.
///
/// Components are private so every value can be constructed only by parsing a
/// string that follows the crate's strict three-component format.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub struct Version {
    major: u16,
    minor: u16,
    patch: u16,
}

impl Version {
    /// Returns the major component.
    #[must_use]
    pub const fn major(&self) -> u16 {
        self.major
    }

    /// Returns the minor component.
    #[must_use]
    pub const fn minor(&self) -> u16 {
        self.minor
    }

    /// Returns the patch component.
    #[must_use]
    pub const fn patch(&self) -> u16 {
        self.patch
    }
}

/// The input was not exactly three canonical decimal `u16` components.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct ParseVersionError;

impl fmt::Display for ParseVersionError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("invalid version")
    }
}

impl Error for ParseVersionError {}

impl FromStr for Version {
    type Err = ParseVersionError;

    /// Parses exactly three dot-separated canonical decimal `u16` components.
    ///
    /// Each component must contain only ASCII digits, with no leading zeroes
    /// except for the component `0` itself. Whitespace, signs, missing or
    /// additional components, and values above `u16::MAX` are rejected.
    ///
    /// # Errors
    ///
    /// Returns [`ParseVersionError`] if the input does not meet these rules.
    fn from_str(input: &str) -> Result<Self, Self::Err> {
        let mut components = input.split('.');
        let major = parse_component(components.next().ok_or(ParseVersionError)?)?;
        let minor = parse_component(components.next().ok_or(ParseVersionError)?)?;
        let patch = parse_component(components.next().ok_or(ParseVersionError)?)?;

        if components.next().is_some() {
            return Err(ParseVersionError);
        }

        Ok(Self {
            major,
            minor,
            patch,
        })
    }
}

fn parse_component(component: &str) -> Result<u16, ParseVersionError> {
    if component.is_empty()
        || (component.len() > 1 && component.starts_with('0'))
        || !component.bytes().all(|byte| byte.is_ascii_digit())
    {
        return Err(ParseVersionError);
    }

    component.parse().map_err(|_| ParseVersionError)
}

